export function getCategoryBySlug(slug: string): ProductCategory | undefined {
  return PRODUCT_CATEGORIES.find(c => c.categorySlug === slug);
}

export function getProductBySlugs(categorySlug: string, productSlug: string): { category: ProductCategory; product: ProductItem } | undefined {
  const category = getCategoryBySlug(categorySlug);
  if (!category) return undefined;
  const product = category.products.find(p => p.slug === productSlug);
  if (!product) return undefined;
  return { category, product };
}

export function getAllProducts(): ProductItem[] {
  return PRODUCT_CATEGORIES.flatMap(c => c.products);
}

